problems.solutionCode:
export interface LineTotal {
  subtotal: number;
  tax: number;
  total: number;
}

function roundCents(value: number): number {
  return Math.round(value * 100) / 100;
}

export function calculateLineTotal(
  unitPrice: number,
  quantity: number,
  taxRate: number,
): LineTotal {
  if (!Number.isFinite(unitPrice) || unitPrice < 0) {
    throw new RangeError("unitPrice must be a finite non-negative number");
  }
  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new RangeError("quantity must be a non-negative integer");
  }
  if (!Number.isFinite(taxRate) || taxRate < 0 || taxRate > 1) {
    throw new RangeError("taxRate must be between 0 and 1");
  }

  const subtotal = roundCents(unitPrice * quantity);
  const tax = roundCents(subtotal * taxRate);
  const total = roundCents(subtotal + tax);
  return { subtotal, tax, total };
}

