  quantity: any,
  taxRate: any,
): LineTotal {
  const subtotal = Math.round(unitPrice * quantity * 100) / 100;
  const tax = Math.round(subtotal * taxRate * 100) / 100;
  return { subtotal, tax, total: Math.round((subtotal + tax) * 100) / 100 };
}

