problems.solutionCode:
export interface FlagRule {
  key: string;
  enabled: boolean;
  rolloutPct: number;
}

function assertValidPct(value: number, label: string, upperExclusive: boolean): void {
  const outOfUpper = upperExclusive ? value >= 100 : value > 100;
  if (!Number.isFinite(value) || value < 0 || outOfUpper) {
    throw new RangeError(`${label} out of range`);
  }
}

export function filterEnabledFlags(
  flags: readonly FlagRule[],
  userBucket: number,
): string[] {
  assertValidPct(userBucket, "userBucket", true);

  const activeKeys: string[] = [];
  for (const flag of flags) {
    assertValidPct(flag.rolloutPct, "rolloutPct", false);
    if (flag.enabled && userBucket < flag.rolloutPct) {
      activeKeys.push(flag.key);
    }
  }
  return activeKeys;
}

