problems.solutionCode:
export type HttpMethod = "GET" | "POST" | "PUT";
export type BackoffStrategy = "fixed" | "exponential";

export interface RetryPlan {
  method: HttpMethod;
  strategy: BackoffStrategy;
  delaysMs: number[];
}

const FIXED_MULTIPLIERS = [1, 1, 1] as const;
const EXPONENTIAL_MULTIPLIERS = [1, 2, 4] as const;

export function createRetryPlan(
  method: HttpMethod,
  baseDelayMs: number,
  strategy: BackoffStrategy,
): RetryPlan {
  if (!Number.isInteger(baseDelayMs) || baseDelayMs <= 0) {
    throw new RangeError("baseDelayMs must be a positive integer");
  }

  const multipliers = strategy === "fixed" ? FIXED_MULTIPLIERS : EXPONENTIAL_MULTIPLIERS;
  const delaysMs = multipliers.map((factor) => baseDelayMs * factor);
  return { method, strategy, delaysMs };
}

