export interface ServiceConfig {
  host: string;
  port: number;
  tls: boolean;
}

export function parseServiceConfig(rawJson: string): ServiceConfig {
  const parsed: any = JSON.parse(rawJson);
  return {
    host: parsed.host,
    port: parsed.port,
    tls: Boolean(parsed.tls),
  };
}

problems.solutionCode:
export interface ServiceConfig {
  host: string;
  port: number;
  tls: boolean;
}

function parseHost(value: unknown): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError("host must be a non-empty string");
  }
  return value.trim();
}

function parsePort(value: unknown): number {
  if (typeof value !== "number") {
    throw new TypeError("port must be a number");
  }
  if (!Number.isInteger(value) || value < 1 || value > 65535) {
    throw new RangeError("port must be an integer between 1 and 65535");
  }
  return value;
}

function parseTls(value: unknown): boolean {
  if (value === undefined) {
    return false;
  }
  if (typeof value !== "boolean") {
    throw new TypeError("tls must be a boolean when provided");
  }
  return value;
}

export function parseServiceConfig(rawJson: string): ServiceConfig {
  const parsed: unknown = JSON.parse(rawJson);
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new TypeError("Config payload must be a JSON object");
  }

  const record = parsed as Record<string, unknown>;
  return {
    host: parseHost(record.host),
    port: parsePort(record.port),
    tls: parseTls(record.tls),
  };
}

