problems.solutionCode:
export type AuditLevel = "info" | "warn" | "error";

export interface AuditEntry {
  actor: string;
  action: string;
  level?: AuditLevel;
}

export function formatAuditEntries(entries: readonly AuditEntry[]): string[] {
  return entries.map((entry) => {
    const actor = entry.actor.trim();
    const action = entry.action.trim();
    if (actor.length === 0 || action.length === 0) {
      throw new TypeError("actor and action must be non-empty strings");
    }
    const level = entry.level ?? "info";
    return `[${level.toUpperCase()}] ${actor}: ${action}`;
  });
}

